function addTableToSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  sheet.appendRow([
    table.id,
    table.name,
    table.capacity,
    'libre',
    '',
    '',
    '',
    ''
  ]);
}

function updateTableDefinitionInSheet(ss, table) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    addTableToSheet(ss, table);
    return;
  }

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(table.id)) {
      sheet.getRange(i + 2, 2).setValue(table.name);
      sheet.getRange(i + 2, 3).setValue(table.capacity);
      if (table.status) sheet.getRange(i + 2, 4).setValue(table.status);
      return;
    }
  }
  // Si no se encontró, agregarlo
  addTableToSheet(ss, table);
}

function deleteTableFromSheet(ss, tableId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.MESAS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(tableId)) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

function saveUserInSheet(ss, user) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();

  const userRow = [
    user.id,
    user.name,
    user.role,
    user.active !== false ? 'SI' : 'NO',
    user.username || user.name.toLowerCase().replace(/\\s+/g, ''),
    user.password || '123'
  ];

  if (lastRow > 1) {
    const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
    for (var i = 0; i < ids.length; i++) {
      if (String(ids[i][0]) === String(user.id)) {
        sheet.getRange(i + 2, 1, 1, 6).setValues([userRow]);
        return;
      }
    }
  }

  sheet.appendRow(userRow);
}

function deleteUserFromSheet(ss, userId) {
  const sheet = ss.getSheetByName(SHEET_NAMES.USUARIOS);
  if (!sheet) return;
  const lastRow = sheet.getLastRow();
  if (lastRow <= 1) return;

  const ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(userId)) {
      sheet.deleteRow(i + 2);
      return;
    }
  }
}

/**
 * =========================================================================
 * FUNCIÓN PARA AUTORIZAR PERMISOS DE GOOGLE DRIVE EN 1 CLIC
 * =========================================================================
 * Si recibes error de "No tengo permiso para subir a Drive", simplemente:
 * 1. En el editor de Apps Script, arriba selecciona esta función: "autorizarPermisosGoogleDrive"
 * 2. Haz clic en el botón "Ejecutar" (Run).
 * 3. Google te mostrará la ventana para conceder permisos a Drive.
 * 4. Haz clic en "Revisar permisos" -> Avanzado -> Permitir. ¡Listo!
 */
function autorizarPermisosGoogleDrive() {
  const folderName = 'ComandaPro_Platos';
  var folders = DriveApp.getFoldersByName(folderName);
  var folder = folders.hasNext() ? folders.next() : DriveApp.createFolder(folderName);
  Logger.log('Permisos de Google Drive activos correctamente. Carpeta verificada: ' + folder.getName());
  return 'Permisos de Drive activos';
}
